#include <string.h>
#include "version_autogenerated.h"
#include "vega_param.h"

extern unsigned int DENALI_CONFIG_CTL[DENALI_CONFIG_CTL_NUM];
extern unsigned int DENALI_CONFIG_PHY[DENALI_CONFIG_PHY_NUM];
extern unsigned int DENALI_CONFIG_CTL_BACKUP[DENALI_CONFIG_CTL_NUM];
extern unsigned int DENALI_CONFIG_PHY_BACKUP[DENALI_CONFIG_PHY_NUM];

spl_dram_info spl_dram;

extern void ddr_config_patch(void);
void sdram_init(void)
{
	unsigned int ddr_version;
	unsigned int tsel_feed;
	unsigned int data_e_sel;
	unsigned int ocd_pu_clk;
	unsigned int ocd_pd_clk;
	unsigned int ocd_pu_cmd;
	unsigned int ocd_pd_cmd;
	unsigned int dfi_cmd_control;
	unsigned int vref_set;
	unsigned int ddr_vref_en;
	unsigned int cwl;
	unsigned int encry_delay;
	unsigned int ddr_vref_cfg;
	unsigned int phy_ddrp_vref_cfg;
	unsigned int phy_ddrb_vref_cfg;
	unsigned int phy_ddrb_vref_en;
	unsigned int phy_ddrp_vref_en;

#ifdef CONFIG_DDR3
	spl_dram.dram_type = 3;
#ifdef DDR_SIP
	ddr_version = 0x2;
#else
	ddr_version = 0x3;
#endif
#elif defined(CONFIG_DDR2)
	spl_dram.dram_type = 2;
	ddr_version = 0x1;
#elif defined(CONFIG_DDR4)
	spl_dram.dram_type = 4;
	ddr_version = 0x4;
#else
#error "only support DDR2, DDR3, DDR4"
#endif

	spl_dram.dram_size = DDR_SIZE * 1024 * 1024;
	//#2: config0[2:0], tsel_feed
	tsel_feed = 0x1;

	//#3: config0[15], data_e_sel, choose the switch of the receiver in DDRIO
	//data_e_sel=0 means switch is controlled by DRAM_CONFIG0[14:11]
	data_e_sel = 0x0;

	//#4: ocd_pu&ocd_pd
	ocd_pu_clk = 0x8;
	ocd_pd_clk = 0x8;
	ocd_pu_cmd = 0x8;
	ocd_pd_cmd = 0x8;

	//#6: config0[31], dfi_cmd_control
	dfi_cmd_control = 0x1;

	//#7: config2[19:16], set SMIC_DDRIO's Vref
	vref_set = 0x0;

	//#8: config3[1:0], set encry_delay
	cwl = (DENALI_CONFIG_CTL[5] >> 16) & 0x1F;
	encry_delay = (cwl - 4) / 2;

	//#9: config7, set reserved vref on decap
	ddr_vref_cfg      = 0;
	phy_ddrp_vref_cfg = 0;
	phy_ddrb_vref_cfg = 0;
	phy_ddrb_vref_en  = 0;
	phy_ddrp_vref_en  = 0;
	ddr_vref_en       = 0;

	spl_dram.dram_config[0] = (tsel_feed<<0) | (data_e_sel<<15) | (dfi_cmd_control<<31);
	spl_dram.dram_config[1] = (ocd_pu_clk<<3) | (ocd_pd_clk<<7) | (ocd_pu_clk<<14) | (ocd_pd_clk<<18) | (ddr_version<<29);
	spl_dram.dram_config[2] = (ocd_pu_cmd<<3) | (ocd_pd_cmd<<7) | (vref_set<<16);
	spl_dram.dram_config[3] = (encry_delay<<0);
	spl_dram.dram_config[4] = (ocd_pu_clk<<0) | (ocd_pd_clk<<4) | (ocd_pu_clk<<8) | (ocd_pd_clk<<12) | (ocd_pu_clk<<16) | (ocd_pd_clk<<20) | (ocd_pu_clk<<24) | (ocd_pd_clk<<28);
	spl_dram.dram_config[5] = 0;
	spl_dram.dram_config[6] = 0;
	spl_dram.dram_config[7] = (ddr_vref_cfg<<0) | (phy_ddrp_vref_cfg<<8) | (phy_ddrb_vref_cfg<<16) | (phy_ddrb_vref_en<<29) | (phy_ddrp_vref_en<<30) | (ddr_vref_en<<31);

	//#8: config3[1:0], set encry_delay
	cwl = (DENALI_CONFIG_CTL_BACKUP[5] >> 16) & 0x1F;
	encry_delay = (cwl - 4) / 2;
	spl_dram.dram_config_backup[0] = (tsel_feed<<0) | (data_e_sel<<15) | (dfi_cmd_control<<31);
	spl_dram.dram_config_backup[1] = (ocd_pu_clk<<3) | (ocd_pd_clk<<7) | (ocd_pu_clk<<14) | (ocd_pd_clk<<18) | (ddr_version<<29);
	spl_dram.dram_config_backup[2] = (ocd_pu_cmd<<3) | (ocd_pd_cmd<<7) | (vref_set<<16);
	spl_dram.dram_config_backup[3] = (encry_delay<<0);
	spl_dram.dram_config_backup[4] = (ocd_pu_clk<<0) | (ocd_pd_clk<<4) | (ocd_pu_clk<<8) | (ocd_pd_clk<<12) | (ocd_pu_clk<<16) | (ocd_pd_clk<<20) | (ocd_pu_clk<<24) | (ocd_pd_clk<<28);
	spl_dram.dram_config_backup[5] = 0;
	spl_dram.dram_config_backup[6] = 0;
	spl_dram.dram_config_backup[7] = (ddr_vref_cfg<<0) | (phy_ddrp_vref_cfg<<8) | (phy_ddrb_vref_cfg<<16) | (phy_ddrb_vref_en<<29) | (phy_ddrp_vref_en<<30) | (ddr_vref_en<<31);

	ddr_config_patch();

	memcpy(spl_dram.DENALI_CONFIG_CTL, DENALI_CONFIG_CTL, sizeof(DENALI_CONFIG_CTL));
	memcpy(spl_dram.DENALI_CONFIG_PHY, DENALI_CONFIG_PHY, sizeof(DENALI_CONFIG_PHY));
	memcpy(spl_dram.DENALI_CONFIG_CTL_BACKUP, DENALI_CONFIG_CTL_BACKUP, sizeof(DENALI_CONFIG_CTL_BACKUP));
	memcpy(spl_dram.DENALI_CONFIG_PHY_BACKUP, DENALI_CONFIG_PHY_BACKUP, sizeof(DENALI_CONFIG_PHY_BACKUP));

	spl_dram.read_dram_priority[0] = 5; // gse/jpeg/vpu/hdcp22/hdmi
	spl_dram.read_dram_priority[1] = 7; // apu/filter/ga/pp/usb
	spl_dram.read_dram_priority[2] = 6; // audio/gmac/nfc/vedio_decoder/sdio
	spl_dram.read_dram_priority[3] = 7; // cortexA7/rcc/secure_hash
	spl_dram.read_dram_priority[4] = 6; // tsio/spi/demux/secure_m2m

	spl_dram.write_dram_priority[0] = 5;
	spl_dram.write_dram_priority[1] = 7;
	spl_dram.write_dram_priority[2] = 6;
	spl_dram.write_dram_priority[3] = 7;
	spl_dram.write_dram_priority[4] = 6;

	spl_dram.vref_value = 0x08; // for DDR4 only
}
